                        begin
                            busreq_cs <=  ST_BUSREQ_WAIT ;
                            if (all_blocks_done) 
                                begin
                                    if ((~(emmc_memwr_req | emmc_memrd_req))) 
                                        begin
                                            busreq_cs <=  ST_BUSREQ_IDLE ;
                                        end
                                end
                            else
                                if (emmc_memwr_req) 
                                    begin
                                        busreq_cs <=  ST_BUSREQ_READ ;
                                        burst_count <=  9'd0 ;
                                    end
                                else
                                    if ((emmc_memrd_req & fifocnt_gteq_axlen)) 
                                        begin
                                            busreq_cs <=  ST_BUSREQ_WRITE ;
                                            burst_count <=  9'd0 ;
                                        end
                        end// ST_BUSREQ_WAIT
                    ST_BUSREQ_READ : 
                        begin
                            // Pipelined AHB-Lite: present address every cycle when ready
                            if ((ahbl_hready_i && (burst_count < axlen_p1))) 
                                begin
                                    burst_count <=  (burst_count + 9'd1) ;
                                    // Increment address after presenting current address
                                    axaddr_r <=  next_addr ;
                                end
                            // Check if we've issued all address beats
                            if ((burst_count >= axlen_p1)) 
                                begin
                                    busreq_cs <=  ST_BUSREQ_DONE ;
                                end
                        end// ST_BUSREQ_READ
                    ST_BUSREQ_WRITE : 
                        begin
                            // Pipelined AHB-Lite: present address every cycle when ready
                            if ((ahbl_hready_i && (burst_count < axlen_p1))) 
                                begin
                                    burst_count <=  (burst_count + 9'd1) ;
                                    // Increment address after presenting current address
                                    axaddr_r <=  next_addr ;
                                end
                            // Check if we've issued all address beats
                            if ((burst_count >= axlen_p1)) 
                                begin
                                    busreq_cs <=  ST_BUSREQ_DONE ;
                                end
                        end// ST_BUSREQ_WRITE
                    ST_BUSREQ_DONE : 
                        begin
                            busreq_cs <=  ST_BUSREQ_DONE ;
                            // Wait for the last data beat to complete
                            if (transfer_done) 
                                begin
                                    busreq_cs <=  ST_BUSREQ_WAIT ;
                                    // Capture the last address used for next block start
                                    axaddr_r <=  ahbl_haddr_r ;
                                end
                        end// ST_BUSREQ_DONE
                    default : 
                        begin
                            // ST_BUSREQ_IDLE
                            busreq_cs <=  ST_BUSREQ_IDLE ;
                            blk_cntr <=  {BLKCNTWID{1'b0}} ;
                            burst_count <=  9'd0 ;
                            data_count <=  9'd0 ;
                            axaddr_r <=  axaddr_base ;
                            axlen_p1 <=  axlen_p1_d ;
                            if ((emmc_memwr_req | emmc_memrd_req)) 
                                begin
                                    busreq_cs <=  ST_BUSREQ_WAIT ;
                                end
                        end// ST_BUSREQ_IDLE
                    endcase 
                end
        end//--always @(posedge clk_i or negedge rst_n_i)--
    //--------------------------------------------
    //-- AHB-Lite Control Signals --
    //--------------------------------------------
    always
        @(posedge clk_i or 
            negedge rst_n_i)
        begin
            if ((~rst_n_i)) 
                begin
                    ahbl_hsel_r <=  1'b0 ;
                    ahbl_haddr_r <=  {AXI4_ADR_WIDTH{1'b0}} ;
                    ahbl_htrans_r <=  HTRANS_IDLE ;
                    ahbl_hwrite_r <=  1'b0 ;
                    ahbl_hsize_r <=  HSIZE_WORD ;
                    ahbl_hburst_r <=  HBURST_INCR ;
                    ahbl_hprot_r <=  4'b0011 ;// Data access, privileged
                    ahbl_hmastlock_r <=  1'b0 ;
                end
            else
                begin
                    case (busreq_cs)
                    ST_BUSREQ_READ : 
                        begin
                            ahbl_hsel_r <=  1'b1 ;
                            ahbl_hwrite_r <=  1'b0 ;// Read
                            ahbl_haddr_r <=  (ahbl_hready_i ? axaddr_r : ahbl_haddr_r) ;
                            // Present new address every cycle when ready
                            if ((ahbl_hready_i && (burst_count < axlen_p1))) 
                                begin
                                    ahbl_htrans_r <=  ((burst_count == 9'd0) ? HTRANS_NONSEQ : HTRANS_SEQ) ;
                                end
                            else
                                begin
                                    ahbl_htrans_r <=  HTRANS_IDLE ;
                                end
                        end
                    ST_BUSREQ_WRITE : 
                        begin
                            ahbl_hsel_r <=  1'b1 ;
                            ahbl_hwrite_r <=  1'b1 ;// Write
                            ahbl_haddr_r <=  (ahbl_hready_i ? axaddr_r : ahbl_haddr_r) ;
                            // Present new address every cycle when ready
                            if ((ahbl_hready_i && (burst_count < axlen_p1))) 
                                begin
                                    ahbl_htrans_r <=  ((burst_count == 9'd0) ? HTRANS_NONSEQ : HTRANS_SEQ) ;
                                end
                            else
                                begin
                                    ahbl_htrans_r <=  HTRANS_IDLE ;
                                end
                        end
                    default : 
                        begin
                            // Deassert HSEL and set IDLE when not in active transfer
                            ahbl_hsel_r <=  1'b0 ;
                            ahbl_htrans_r <=  HTRANS_IDLE ;
                        end
                    endcase 
                end
        end//--always @(posedge clk_i or negedge rst_n_i)--
    //--------------------------------------------
    //-- AHB-Lite Write Data --
    //--------------------------------------------
    always
        @(posedge clk_i or 
            negedge rst_n_i)
        begin
            if ((~rst_n_i)) 
                begin
                    ahbl_hwdata_r <=  32'h0 ;
                end
            else
                begin
                    // Write data is presented in data phase (one cycle after address)
                    if (((ahb_data_phase & ahbl_hready_i) & (~dat_fifo_emty))) 
                        begin
                            ahbl_hwdata_r <=  dat_fifo_rdata ;
                        end
                end
        end//--always @(posedge clk_i or negedge rst_n_i)--
    //--------------------------------------------
    //-- FIFO Write Logic (from AHB reads or command processor) --
    //--------------------------------------------
    always
        @(posedge clk_i or 
            negedge rst_n_i)
        begin
            if ((~rst_n_i)) 
                begin
                    /*AUTORESET*/
                    // Beginning of autoreset for uninitialized flops
                    dat_fifo_wdata <=  32'h0 ;
                    dat_fifo_wren <=  1'h0 ;
                    // End of automatics
                end
            else
                begin
                    dat_fifo_wren <=  (((emmc_memrd_req & (~dat_fifo_full)) & cmd_proc_mem_wren) | ((emmc_memwr_req & (~dat_fifo_full)) & rd_dat_vld)) ;
                    dat_fifo_wdata <=  (emmc_memrd_req ? cmd_proc_mem_wdat : ahbl_hrdata_i) ;
                end
        end//--always @(posedge clk_i or negedge rst_n_i)--
    //--------------------------------------------
    //-- FIFO Counter and Flow Control --
    //--------------------------------------------
    always
        @(posedge clk_i or 
            negedge rst_n_i)
        begin
            if ((~rst_n_i)) 
                begin
                    /*AUTORESET*/
                    // Beginning of autoreset for uninitialized flops
                    fifo_cntr <=  {FCNTWID{1'b0}} ;
                    fifocnt_gteq_axlen <=  1'h0 ;
                    mem_avail <=  1'h0 ;
                    mem_free <=  1'h0 ;
                    // End of automatics
                end
            else
                begin
                    fifocnt_gteq_axlen <=  (fifo_cntr >= axlen_p1) ;
                    mem_avail <=  ((|fifo_cntr) & (fifo_cntr >= (block_size[15:2] & {FCNTWID{1'b1}}))) ;
                    mem_free <=  (fifo_cntr <= (block_size[15:2] & {FCNTWID{1'b1}})) ;
                    case ({dat_fifo_wren,
                            dat_fifo_rden})
                    2'b01 : 
                        fifo_cntr <=  (fifo_cntr - {{(FCNTWID - 1){1'b0}},
                                1'b1}) ;
                    2'b10 : 
                        fifo_cntr <=  (fifo_cntr + {{(FCNTWID - 1){1'b0}},
                                1'b1}) ;
                    default : 
                        fifo_cntr <=  fifo_cntr ;
                    endcase 
                end
        end//--always @(posedge clk_i or negedge rst_n_i)--
    //--------------------------------------------
    //-- Block Counter Logic --
    //--------------------------------------------
    generate
        if ((MAX_BLOCK_SIZE > 1024)) 
            begin : gen_blk_gt1KB
                reg [(PBCNTWID - 1):0] partial_bcnt ; 
                reg block_last_r ; 
                reg [1:0] req_done_dly ; 
                wire [5:0] max_partial_bcnt ; 
                assign incr_blk_cnt = (req_done_dly[1] & block_last) ; 
                assign block_last = block_last_r ; 
                assign max_partial_bcnt = ((MAX_BLOCK_SIZE < 4096) ? (block_size[11:10] & {6{1'b1}}) : ((MAX_BLOCK_SIZE < 8192) ? (block_size[12:10] & {6{1'b1}}) : ((MAX_BLOCK_SIZE < 16384) ? (block_size[13:10] & {6{1'b1}}) : ((MAX_BLOCK_SIZE < 32768) ? (block_size[14:10] & {6{1'b1}}) : 6'd0)))) ; 
                //--------------------------------------------
                //-- Sequential block --
                //--------------------------------------------
                always
                    @(posedge clk_i or 
                        negedge rst_n_i)
                    begin
                        if ((~rst_n_i)) 
                            begin
                                /*AUTORESET*/
                                // Beginning of autoreset for uninitialized flops
                                block_last_r <=  1'h0 ;
                                partial_bcnt <=  {PBCNTWID{1'b0}} ;
                                req_done_dly <=  2'h0 ;
                                // End of automatics
                            end
                        else
                            begin
                                req_done_dly <=  {req_done_dly[0],
                                        (wr_req_done | rd_req_done)} ;// need to delay to wait for updated block_last_r
                                if ((busreq_cs == ST_BUSREQ_IDLE)) 
                                    begin
                                        partial_bcnt <=  {PBCNTWID{1'b0}} ;
                                        block_last_r <=  1'b0 ;
                                    end
                                else
                                    begin
                                        block_last_r <=  (partial_bcnt == (max_partial_bcnt & {PBCNTWID{1'b1}})) ;
                                        if ((wr_req_done | rd_req_done)) 
                                            begin
                                                partial_bcnt <=  (partial_bcnt + {{(PBCNTWID - 1){1'b0}},
                                                        (~block_last_r)}) ;
                                            end
                                        else
                                            if (incr_blk_cnt) 
                                                begin
                                                    partial_bcnt <=  {PBCNTWID{1'b0}} ;
                                                end
                                    end
                            end
                    end//--always @(posedge clk_i or negedge rst_n_i)--
            end
        else
            begin : gen_blk_lteq1KB
                assign block_last = 1'b1 ; 
                assign incr_blk_cnt = ((wr_req_done | rd_req_done) & block_last) ; 
            end
        if (SIMULATION) 
            begin : gen_sim
                // -----------------------------------
                // For Simulation use only
                // State in ASCII for readability
                // -----------------------------------
                /*AUTOASCIIENUM("busreq_cs", "_bus_cs_", "ST_BUSREQ_")*/
                // Beginning of automatic ASCII enum decoding
                reg [39:0] _bus_cs_ ; // Decode of busreq_cs
                always
                    @(busreq_cs)
                    begin
                        case ({busreq_cs})
                        ST_BUSREQ_IDLE : 
                            _bus_cs_ = "idle " ;
                        ST_BUSREQ_WAIT : 
                            _bus_cs_ = "wait " ;
                        ST_BUSREQ_READ : 
                            _bus_cs_ = "read " ;
                        ST_BUSREQ_WRITE : 
                            _bus_cs_ = "write" ;
                        ST_BUSREQ_DONE : 
                            _bus_cs_ = "done " ;
                        default : 
                            _bus_cs_ = "%Erro" ;
                        endcase 
                    end
            end
    endgenerate
    //--------------------------------------------------------------------------
    //--- Module Instantiation ---
    //--------------------------------------------------------------------------
    emmc0_ipgen_emmc_fifo #(.SIMULATION(SIMULATION),
            .DEVICE_FAMILY(DEVICE_FAMILY),
            .FIFO_IMPL(FIFO_IMPL),
            .MEM_IMPL(MEM_IMPL),
            .PIPE_IMPL(PIPE_IMPL),
            .CLKDOMAIN(CLKDOMAIN),
            .DWID(32),
            .SIZE(FIFO_DEPTH),
            .AFUL_LVL(FIFO_AFUL_LVL),
            .INV_PMI_WCLK(0),
            .INV_PMI_RCLK(0)) u_dat_fifo (// Parameters
            // Inputs
            .wclk(clk_i), 
                .rclk(clk_i), 
                .wrst_n(rst_n_i), 
                .rrst_n(rst_n_i), 
                .wren(dat_fifo_wren), 
                .wdat(dat_fifo_wdata[31:0]), 
                .rden(dat_fifo_rden), 
                // Outputs
            .rdat(dat_fifo_rdata[31:0]), 
                .emty(dat_fifo_emty), 
                .full(dat_fifo_full), 
                .aful(dat_fifo_aful), 
                .aemt(dat_fifo_aemt)) ; 

//--emmc_ahbl_m--
endmodule



