                            .emmc_memrd_req(emmc_memrd_req), 
                            .emmc_memwr_req(emmc_memwr_req), 
                            .cmd_proc_mem_rden(cmd_proc_mem_rden), 
                            .cmd_proc_mem_wdat(cmd_proc_mem_wdat[31:0]), 
                            .cmd_proc_mem_wren(cmd_proc_mem_wren), 
